const experimentSplit = String(atualOriginal.experiment_split || '').toUpperCase().trim();
const benchmark = executionMode === 'BENCHMARK' || ['TEST','TESTE','BENCHMARK'].includes(experimentSplit);
let candidateLimit = 20;
