function readNode(name) {
  try {
    return $(name).first().json || {};
  } catch(e) {
    return {};
  }
}
const norm = readNode('Normalizar Dedup');
const pg = readNode('PG: Erro IA Dedup');
const estruturado = readNode('Estruturar Chamado');
const c = norm.chamado || estruturado.chamado || {};
const id = Number(c.id || pg.id || 0);
const erro = String(norm.mensagem_erro || norm.erro || norm.error || pg.ultimo_erro_ia || 'Resposta invalida ou indisponibilidade da IA de deduplicacao');
const tentativas = Number(pg.tentativas_ia_dedup ?? norm.tentativas_ia_dedup ?? c.tentativas_ia_dedup ?? 0);
const tituloOriginal = String(c.titulo || c.name || ('Chamado #' + (id || 'sem ID'))).trim();
const tituloSemTag = tituloOriginal.replace(/^\[Erro IA\]\s*/i, '').trim() || ('Chamado #' + (id || 'sem ID'));
const tituloNovo = ('[Erro IA] ' + tituloSemTag).slice(0, 250);
const aviso = [
  '[TRIAGEM_IA][ERRO_DEDUP]',
  'A automacao nao conseguiu obter uma resposta valida da IA para a verificacao de duplicidade deste chamado.',
  'O limite de reprocessamento automatico foi atingido e a demanda ficou marcada para revisao tecnica.',
  '',
  'Chamado: #' + (id || 'N/A'),
  'Titulo original: ' + tituloOriginal,
  'Tentativas IA dedup: ' + (Number.isFinite(tentativas) ? tentativas : 'N/A'),
  'Erro registrado: ' + erro,
  '',
  'Acao esperada: equipe de infraestrutura deve verificar credencial/rede/modelo IA e decidir o reprocessamento.'
].join('\n');
const assunto = '[Triagem IA][WF02] Erro de deduplicacao #' + (id || 'N/A');
const corpo = [
  'WF02 atingiu o limite de tentativas da IA de deduplicacao.',
  '',
  'Chamado: #' + (id || 'N/A'),
  'Titulo: ' + tituloOriginal,
  'Status atual: ' + (c.status_nome || c.status_num || 'N/A'),
  'Solicitante: ' + (c.solicitante || 'N/A') + ' <' + (c.email_solicitante || '') + '>',
  'Localizacao: ' + (c.localizacao || 'N/A'),
  'Tentativas IA dedup: ' + (Number.isFinite(tentativas) ? tentativas : 'N/A'),
  'Erro: ' + erro
].join('\n');
console.log('[WF02][LOG] Erro dedup final preparado #' + (id || 'N/A') + ' tentativas=' + tentativas);
return [{json:{
  chamado:{...c,id,titulo:tituloNovo},
  titulo_novo:tituloNovo,
  aviso_glpi:aviso,
  email_ti:{assunto,corpo},
  erro,
  tentativas
}}];

const c = $('Normalizar Dedup').first().json.chamado;
const d = $('Normalizar Dedup').first().json.duplicidade;
const ref = d.chamado_referencia || {};
const pg = $('PG: Marcar Possível Duplicado').first().json || {};
const token = String(pg.fiscal_decision_token || '').trim();
if (!token) {
  throw new Error('Token fiscal ausente apos PG: Marcar Possível Duplicado');
}
let base = 'http://localhost:5678/webhook/fiscal-decisao-fiscal-ic-2026';
try {
  if (typeof process !== 'undefined' && process.env.FISCAL_DECISION_BASE_URL) base = process.env.FISCAL_DECISION_BASE_URL;
} catch(e) {}
const marker = `[WF02_DUPLICIDADE:${c.id}:${token}]`;
const lC = base + '?decisao=confirmar&chamado_id=' + c.id + '&ref_id=' + (d.chamado_referencia_id || '') + '&token=' + encodeURIComponent(token);
const lN = base + '?decisao=nao_duplicado&chamado_id=' + c.id + '&token=' + encodeURIComponent(token);
const cleanTitle = String(c.titulo || ('#' + c.id)).replace(/^\[Duplicado\]\s*/i, '');
const titulo = '[Duplicado] ' + cleanTitle;
const corpo = [
  marker,
  '[TRIAGEM_IA] Possivel duplicata do chamado #' + (ref.id || d.chamado_referencia_id || 'N/A'),
  'ID do match: ' + (ref.id || d.chamado_referencia_id || 'N/A'),
  'Titulo ref: ' + (ref.titulo || 'N/A'),
  'Status ref: ' + (ref.status_nome || 'N/A'),
  'Descricao ref: ' + (ref.descricao || 'N/A'),
  'Local ref: ' + (ref.localizacao || 'N/A'),
  'Solicitante ref: ' + (ref.solicitante || 'N/A') + ' <' + (ref.email_solicitante || '') + '>',
  'Motivo: ' + d.justificativa,
  '',
  'LINKS DE DECISAO:',
  'Confirmar Duplicidade: ' + lC,
  'Nao duplicado: ' + lN,
  '',
  'resumo_visual: Chamado #' + c.id + ' marcado como possivel duplicado do chamado #' + (ref.id || d.chamado_referencia_id || 'N/A') + '. Proxima acao: aguardar decisao fiscal no GLPI.'
].join('\n');
console.log('[WF02][LOG] Followup duplicado preparado #' + c.id + ' token=' + token.slice(0, 8));
return [{json:{
  chamado:c,
  titulo_novo:titulo,
  corpo,
  linkConfirmar:lC,
  linkNaoDup:lN,
  fiscal_decision_token:token,
  fiscal_token_expira_em:pg.fiscal_token_expira_em,
