const ch = {...($('Estruturar Chamado').first().json.chamado || {})};
const baseUrl = String((typeof process !== 'undefined' && process.env.GLPI_API_URL) || 'http://host.docker.internal:9080/apirest.php').replace(/\/$/, '');
const appToken = String((typeof process !== 'undefined' && process.env.GLPI_APP_TOKEN) || 'SeedToken2024CampusRP');
const sessionToken = String($('GLPI: Iniciar Sessão').first().json.session_token || '');
const headers = {'App-Token': appToken, 'Session-Token': sessionToken, 'Content-Type': 'application/json'};
function norm(s) {
  return String(s || '')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ').trim();
}
function score(text, terms) {
  let total = 0;
  for (const term of terms) {
    if (typeof term === 'string') {
      const t = norm(term);
      if (!t) continue;
      const escaped = t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      if (new RegExp('(^| )' + escaped + '( |$)').test(text)) total += 1;
    } else if (term.test(text)) total += 1;
  }
  return total;
}
async function glpi(path) {
  try {
    return await helpers.httpRequest({method:'GET', url:baseUrl + path, headers, json:true});
  } catch (e) {
    console.log('[WF02][LOG] Falha ao consultar categoria GLPI ' + path + ': ' + e.message);
    return null;
  }
}
const texto = norm([ch.titulo, ch.descricao, ch.localizacao].join(' '));
const regras = [
  {codigo:'ELETRICA', nomes:['Elétrica','Eletrica'], termos:['eletrica','eletrico','eletricista','energia','tomada','disjuntor','lampada','lâmpada','luminaria','luminária','reator','interruptor','fiacao','fiação','curto circuito','quadro de energia']},
  {codigo:'HIDRAULICA', nomes:['Hidráulica','Hidraulica'], termos:['hidraulica','hidráulica','bombeiro','torneira','vaso sanitario','vaso sanitário','cano','tubulacao','tubulação','esgoto','descarga','pia','banheiro','hidraulica','hidráulica','vazamento de agua','vazamento de água','caixa d agua','caixa d’água','e t a','eta','estacao de tratamento','tratamento de agua','cloro','bomba da eta','filtro da eta']},
  {codigo:'SERVICOS_TERCEIRIZADOS', nomes:['Suporte a Serviços Terceirizados','Suporte a Servicos Terceirizados'], termos:['ar condicionado','ar-condicionado','climatizador','split','elevador','camera','câmera','cftv','alarme','controle de acesso','autoclave','caldeira','projetor','impressora','televisao','televisão','equipamento de laboratorio','equipamento de laboratório','portao automatico','portão automático','motor de portao','motor de portão','garantia','fabricante']},
  {codigo:'MECANICA_GERAL', nomes:['Mecânica Geral','Mecanica Geral'], termos:['mecanica','mecânica','mecanico','mecânico','motor','engrenagem','rolamento','maquina','máquina','equipamento mecanico','equipamento mecânico','bomba mecanica','bomba mecânica']},
  {codigo:'CARPINTARIA_MARCENARIA', nomes:['Carpintaria / Marcenaria','Carpintaria','Marcenaria'], termos:['carpintaria','marcenaria','madeira','porta','fechadura','macaneta','maçaneta','janela','persiana','armario','armário','corrimão de madeira','corrimao de madeira']},
  {codigo:'LIMPEZA_JARDINAGEM', nomes:['Limpeza e Jardinagem','Jardinagem','Limpeza'], termos:['limpeza','jardinagem','jardim','poda','grama','mato','capina','rocada','roçada','arvore','árvore','galho','calha suja','limpar calha']},
  {codigo:'MANUTENCAO_PREDIAL', nomes:['Manutenção Predial','Manutencao Predial'], termos:['manutencao predial','manutenção predial','pintura','pintar','tinta','retoque','parede suja','descascando','mofo','construcao','construção','alvenaria','parede','reboco','piso','ceramica','cerâmica','cimento','argamassa','concreto','calcada','calçada','muro','rachadura','infiltracao','infiltração','telha','goteira','forro','serralheria','solda','portao','portão','grade','ferro','metal','estrutura metalica','estrutura metálica','corrimao','corrimão','alambrado']}
];
let escolhido = null;
for (const regra of regras) {
  const s = score(texto, regra.termos);
  if (s > 0 && (!escolhido || s > escolhido.score)) escolhido = {...regra, score:s};
}
let categorias = [];
const rawCats = await glpi('/ITILCategory?range=0-9999');
if (Array.isArray(rawCats)) categorias = rawCats;
const cats = categorias.map(c => ({id:Number(c.id), name:String(c.name || ''), completename:String(c.completename || c.name || ''), norm:norm(c.completename || c.name || '')})).filter(c => c.id > 0);
function findCategoria(nomes) {
  for (const nome of nomes) {
    const n = norm(nome);
    let found = cats.find(c => c.norm === n);
    if (found) return found;
    found = cats.find(c => c.norm.includes(n) || n.includes(c.norm));
    if (found) return found;
  }
  return null;
}
const atualId = Number(ch.tipo_servico_id || 0);
const atualNome = String(ch.tipo_servico || '');
const alvo = escolhido ? findCategoria(escolhido.nomes) : null;
const precisa = Boolean(alvo && alvo.id && alvo.id !== atualId);
const motivo = escolhido
  ? 'Heuristica tecnica detectou categoria local ' + escolhido.codigo + ' por palavras-chave do chamado.'
  : 'Nenhuma categoria tecnica foi detectada com seguranca antes da deduplicacao.';
const chamado = alvo ? {...ch, tipo_servico:alvo.completename || alvo.name, tipo_servico_id:alvo.id, categoria_original_id:atualId || null, categoria_original_nome:atualNome, categoria_sugerida_codigo:escolhido.codigo} : ch;
console.log('[WF02][LOG] Categoria tecnica #' + ch.id + ' atual=' + (atualId || atualNome || 'N/A') + ' alvo=' + (alvo ? alvo.id + ':' + alvo.completename : 'N/A') + ' precisa=' + precisa);
return [{json:{
  chamado,
  categoria_precisa_correcao:precisa,
  categoria_original_id:atualId || null,
  categoria_original_nome:atualNome,
  categoria_sugerida_id:alvo?.id || null,
  categoria_sugerida_nome:alvo?.completename || alvo?.name || null,
  categoria_sugerida_codigo:escolhido?.codigo || null,
  motivo_categoria:motivo,
  resumo_visual: precisa
    ? 'Chamado #' + ch.id + ' teve categoria local ' + (escolhido?.codigo || 'N/A') + ' mapeada antes da deduplicacao: ' + (atualNome || atualId || 'sem categoria') + ' -> ' + (alvo.completename || alvo.name) + '.'
    : 'Chamado #' + ch.id + ' nao exigiu correcao automatica de categoria antes da deduplicacao.',
  fase:'WF02_VALIDAR_CATEGORIA',
  chamado_id:ch.id,
  status_anterior:atualNome || atualId || null,
  status_novo:alvo?.completename || alvo?.name || null,
  proxima_acao: precisa ? 'CORRIGIR_CATEGORIA_GLPI' : 'SEGUIR_DEDUP'
}}];

